sp_PagarConta	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_PagarConta`(\n\n    IN p_idContaPagar INT,\n\n    IN p_valorPago    DECIMAL(10,2),\n\n    IN p_dthPagamento DATETIME\n\n)\nBEGIN\n\n    UPDATE ContaPagar SET\n\n        valorPago    = valorPago + p_valorPago,\n\n        dthPagamento = p_dthPagamento,\n\n        status       = CASE\n\n                         WHEN valorPago + p_valorPago >= valorTotal THEN 'PAGO'\n\n                         ELSE 'ABERTO'\n\n                       END\n\n    WHERE idContaPagar = p_idContaPagar;\n\n\n\n    INSERT INTO HistoricoContaPagar (idContaPagar, valorPago, dthPagamento)\n\n    VALUES (p_idContaPagar, p_valorPago, p_dthPagamento);\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
